# A real renv project: .Rprofile sources renv/activate.R (generated by renv and
# committed, as authors do), which puts the PROJECT library on the path and drops
# the user library. praise is in renv.lock and nowhere else this session can see,
# so the step passes only if renv::restore() put it where activate.R looks — and
# the library is still usable offline (renv's default links it into a cache the
# run never sees).
library(praise)
stopifnot(grepl("renv/library", find.package("praise"), fixed = TRUE))
dir.create("results", showWarnings = FALSE)
writeLines(as.character(packageVersion("praise")), "results/version.txt")
